functions.port_priority_set_chest:
summon minecraft:item_frame ~1 ~2 ~ {Facing:5,Invulnerable:1b,Invisible:1b,Fixed:1b,Tags:["currentItemFrame","PortPriority"],Item:{}}
summon minecraft:item_frame ~-1 ~2 ~ {Facing:4,Invulnerable:1b,Invisible:1b,Fixed:1b,Tags:["currentItemFrame","PortPriority"],Item:{}}
summon minecraft:item_frame ~ ~2 ~1 {Facing:3,Invulnerable:1b,Invisible:1b,Fixed:1b,Tags:["currentItemFrame","PortPriority"],Item:{}}
summon minecraft:item_frame ~ ~2 ~-1 {Facing:2,Invulnerable:1b,Invisible:1b,Fixed:1b,Tags:["currentItemFrame","PortPriority"],Item:{}}
tag @e[tag=PortPriorityItem,sort=random,limit=1] add temp
execute if entity @e[tag=temp,tag=CopperIngot] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:copper_ingot",count:1}}
execute if entity @e[tag=temp,tag=NetheriteIngot] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:netherite_ingot",count:1}}
execute if entity @e[tag=temp,tag=PrismarineShard] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:prismarine_shard",count:1}}
execute if entity @e[tag=temp,tag=Quartz] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:quartz",count:1}}
execute if entity @e[tag=temp,tag=GoldIngot] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:gold_ingot",count:1}}
execute if entity @e[tag=temp,tag=Emerald] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:emerald",count:1}}
execute if entity @e[tag=temp,tag=Diamond] as @e[tag=currentItemFrame] run data merge entity @s {Item:{id:"minecraft:diamond",count:1}}
execute positioned ~ ~1 ~ run function mcp:port_priority_set_independent_chest
scoreboard players add currentChest variables 1
tag @s add PortPriority
execute if score currentChest variables matches 1 run tag @s add 1
execute if score currentChest variables matches 2 run tag @s add 2
execute if score currentChest variables matches 3 run tag @s add 3
execute if score currentChest variables matches 4 run tag @s add 4
execute if score currentChest variables matches 5 run tag @s add 5
execute if score currentChest variables matches 6 run tag @s add 6
execute if score currentChest variables matches 7 run tag @s add 7
execute if score currentChest variables matches 1 run clone ~ ~1 ~ ~ ~1 ~ -360 13 -308
execute if score currentChest variables matches 2 run clone ~ ~1 ~ ~ ~1 ~ -362 13 -308
execute if score currentChest variables matches 3 run clone ~ ~1 ~ ~ ~1 ~ -364 13 -308
execute if score currentChest variables matches 4 run clone ~ ~1 ~ ~ ~1 ~ -366 13 -308
execute if score currentChest variables matches 5 run clone ~ ~1 ~ ~ ~1 ~ -368 13 -308
execute if score currentChest variables matches 6 run clone ~ ~1 ~ ~ ~1 ~ -370 13 -308
execute if score currentChest variables matches 7 run clone ~ ~1 ~ ~ ~1 ~ -372 13 -308
execute unless score NightTime variables matches 1 run setblock ~ ~2 ~ minecraft:black_stained_glass_pane
tag @e[tag=currentItemFrame] remove currentItemFrame
kill @e[tag=temp]
execute if score currentChest variables matches 7 run scoreboard players reset currentChest variables

